    async def _do(self, request: _ApiRequest) -> httpx.Response:
        path = request.path_fmt.format(
            *[urllib.parse.quote(a, safe="") for a in request.path_args]
        )
        json_body = None
        if request.body is not None:
            if isinstance(request.body, BaseModel):
                json_body = request.body.model_dump(mode="json")
            else:
                json_body = request.body
        response = await self._http_client.request(request.method, path, json=json_body)
        if response.status_code != request.success_code:
            raise ResponseError(status_code=response.status_code, body=response.text)
        return response

    async def _do_json(self, response_type: type[_T], request: _ApiRequest) -> _T:
        response = await self._do(request)
        content_type = response.headers.get("content-type", "")
        if not content_type.startswith("application/json"):
            raise ValueError(
                f"unexpected content type {content_type!r}, expected application/json"
            )
        return response_type.model_validate_json(response.content)
